const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => [...root.querySelectorAll(s)];
const state = {
  user:null, csrf:null, page:'dashboard',
  audioCtx:null, micStream:null, mediaRecorder:null, chunks:[], recordedAssets:[], meterRAF:null,
  beatTimer:null, beatStep:0,
  room:null, localStream:null, screenStream:null, peers:new Map(), signalAfter:0, messageAfter:0, roomPoll:null, mediaStarted:false, iceServers:[]
};

const NAV = [
  ['dashboard','⌂','Command'],['studio','◉','Studio'],['beats','▦','Beat Lab'],['live','◎','Live Sessions'],
  ['releases','◆','Releases'],['royalties','≋','Royalties'],['career','▣','Career / EPK'],['legal','§','Legal Center'],['account','⚿','Account'],['admin','✦','Master']
];
const TITLES = {
  dashboard:['PRIVATE NETWORK','Command Center'],studio:['RECORD • MIX • SAVE','Recording Studio'],beats:['PRODUCER ECOSYSTEM','Beat Lab + Plugins'],
  live:['PRIVATE COLLABORATION','Live Sessions'],releases:['VERIFIED CREATOR VAULT','Releases + Rights'],royalties:['EDUCATION CENTER','Royalties + Music Business'],
  career:['ARTIST DEVELOPMENT','Career + EPK'],legal:['PRIVACY • COPYRIGHT • BUSINESS','Legal + Rights Center'],account:['SECURITY','Account Security'],admin:['OWNER AUTHORITY','Master Control']
};

function esc(v=''){return String(v).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function fmtBytes(n=0){if(n<1024)return `${n} B`; if(n<1048576)return `${(n/1024).toFixed(1)} KB`; return `${(n/1048576).toFixed(1)} MB`}
function fmtDate(v){try{return new Date(v).toLocaleString()}catch{return v||''}}
function roleLabel(r){return ({super_admin:'MASTER OWNER',admin:'ADMIN',verified_artist:'VERIFIED ARTIST',verified_producer:'VERIFIED PRODUCER',creator:'CREATOR'})[r]||r.toUpperCase()}
function toast(msg,type=''){const t=$('#toast');t.textContent=msg;t.className=`toast show ${type}`;clearTimeout(t._x);t._x=setTimeout(()=>t.className='toast',3100)}
function openModal(html){$('#modalBody').innerHTML=html;$('#modal').classList.remove('hidden')}
function closeModal(){ $('#modal').classList.add('hidden'); $('#modalBody').innerHTML='' }
$('#modalClose').onclick=closeModal; $('#modal').addEventListener('click',e=>{if(e.target.id==='modal')closeModal()});

async function api(path,{method='GET',body=null,headers={}}={}){
  const opts={method,credentials:'same-origin',headers:{...headers}};
  if(state.csrf && method!=='GET') opts.headers['X-IHD-CSRF']=state.csrf;
  if(body!==null){opts.headers['Content-Type']='application/json';opts.body=JSON.stringify(body)}
  const r=await fetch(path,opts); let data={}; try{data=await r.json()}catch{}
  if(r.status===401 && !['/api/login','/api/register'].includes(path)){lockGate();throw new Error('Session expired')}
  if(!r.ok) throw new Error(data.message||data.error||`Request failed (${r.status})`);
  return data;
}
async function upload(kind,file,onProgress){
  if(!file) throw new Error('Choose a file first.');
  const xhr=new XMLHttpRequest();
  return new Promise((resolve,reject)=>{
    xhr.open('POST',`/api/upload/${kind}`);xhr.responseType='json';xhr.setRequestHeader('X-IHD-CSRF',state.csrf);xhr.setRequestHeader('X-IHD-Filename',encodeURIComponent(file.name));xhr.setRequestHeader('Content-Type',file.type||'application/octet-stream');
    xhr.upload.onprogress=e=>{if(e.lengthComputable&&onProgress)onProgress(e.loaded/e.total)};
    xhr.onload=()=>xhr.status>=200&&xhr.status<300?resolve(xhr.response):reject(new Error(xhr.response?.message||`Upload failed (${xhr.status})`));
    xhr.onerror=()=>reject(new Error('Network upload failed.'));xhr.send(file);
  });
}

async function boot(){
  try{const me=await api('/api/me');state.user=me.user;state.csrf=me.csrf;enterApp()}catch{$('#gate').classList.remove('hidden');$('#app').classList.add('hidden')}
}
function showAuth(mode='login'){
  const login=mode==='login';
  $('#loginForm').classList.toggle('hidden',!login);
  $('#registerForm').classList.toggle('hidden',login);
  $('#authTabLogin').classList.toggle('active',login);
  $('#authTabRegister').classList.toggle('active',!login);
  $('#loginError').textContent='';$('#registerError').textContent='';
}
$('#authTabLogin').onclick=()=>showAuth('login');
$('#authTabRegister').onclick=()=>showAuth('register');
$('#loginForm').addEventListener('submit',async e=>{e.preventDefault();$('#loginError').textContent='';const btn=$('#loginForm button[type=submit]');btn.disabled=true;try{const d=await api('/api/login',{method:'POST',body:{email:$('#loginEmail').value,password:$('#loginPassword').value}});state.user=d.user;state.csrf=d.csrf;enterApp()}catch(err){$('#loginError').textContent=err.message}finally{btn.disabled=false}});
$('#registerForm').addEventListener('submit',async e=>{
  e.preventDefault();$('#registerError').textContent='';$('#registerSuccess').textContent='';
  const btn=$('#registerForm button[type=submit]');btn.disabled=true;
  try{
    const email=$('#registerEmail').value.trim();
    const d=await api('/api/register',{method:'POST',body:{display_name:$('#registerName').value,email,password:$('#registerPassword').value,confirm_password:$('#registerConfirm').value,terms_accepted:$('#registerTerms').checked}});
    $('#loginEmail').value=email;$('#loginPassword').value='';
    $('#registerPassword').value=$('#registerConfirm').value='';$('#registerTerms').checked=false;
    showAuth('login');$('#loginError').textContent='Account created successfully. Sign in with the password you just created.';
    toast(d.message||'Account created. Sign in now.','good');
  }catch(err){$('#registerError').textContent=err.message}finally{btn.disabled=false}
});
async function logout(){try{await api('/api/logout',{method:'POST',body:{}})}catch{}lockGate()}
function lockGate(){cleanupRoom();if(state.micStream)state.micStream.getTracks().forEach(t=>t.stop());state.user=null;state.csrf=null;$('#app').classList.add('hidden');$('#gate').classList.remove('hidden');$('#loginPassword').value='';showAuth('login')}
$('#logoutBtn').onclick=logout;
$('#refreshBtn').onclick=()=>go(state.page);
$('#changePasswordBtn').onclick=()=>go('account');

function enterApp(){
  $('#gate').classList.add('hidden');$('#app').classList.remove('hidden');$('#accountName').textContent=state.user.display_name;$('#accountRole').textContent=roleLabel(state.user.role);
  renderNav();
  const params=new URLSearchParams(location.search);
  const sharedRoomCode=params.get('room')?.trim().toUpperCase();
  if(sharedRoomCode){
    go('live').then(()=>setTimeout(()=>{const joinCode=$('#joinCode'); if(joinCode){joinCode.value=sharedRoomCode; $('#joinRoom').click();}},200));
  } else {
    go(state.user.must_change_password?'account':'dashboard');
  }
  if(state.user.must_change_password) toast('Change the temporary password before continuing.','bad');
}
function renderNav(){const nav=$('#nav');nav.innerHTML='';NAV.filter(([id])=>id!=='admin'||['super_admin','admin'].includes(state.user.role)).forEach(([id,icon,label])=>{const b=document.createElement('button');b.className='nav-btn';b.dataset.page=id;b.innerHTML=`<span class="nav-icon">${icon}</span><span class="nav-label">${label}</span>`;b.onclick=()=>go(id);nav.appendChild(b)})}
async function go(page){
  cleanupPage();state.page=page;$$('.nav-btn').forEach(b=>b.classList.toggle('active',b.dataset.page===page));const [eye,title]=TITLES[page]||['PRIVATE NETWORK','IT HIT DIFFERENT'];$('#sectionEyebrow').textContent=eye;$('#pageTitle').textContent=title;$('#content').innerHTML='<div class="empty">Loading secure workspace…</div>';
  try{await ({dashboard:renderDashboard,studio:renderStudio,beats:renderBeats,live:renderLive,releases:renderReleases,royalties:renderRoyalties,career:renderCareer,legal:renderLegal,account:renderAccount,admin:renderAdmin}[page]||renderDashboard)()}catch(err){$('#content').innerHTML=`<div class="panel"><h3>Could not load this section</h3><p class="muted">${esc(err.message)}</p></div>`}
}
function cleanupPage(){if(state.beatTimer){clearTimeout(state.beatTimer);state.beatTimer=null}if(state.meterRAF){cancelAnimationFrame(state.meterRAF);state.meterRAF=null}if(state.page==='live')cleanupRoom()}

