  $('#content').innerHTML=`
  <div class="hero panel"><div><p class="eyebrow">IT HIT DIFFERENT LLC</p><h3>One private home for the record and the business behind it.</h3><p>Capture vocals, build beats, collaborate live, document ownership, publish verified releases and grow your artist infrastructure without handing control of the platform to outsiders.</p></div><div class="hero-stamp"><b>IHD</b>OWN THE PROCESS</div></div>
  ${inv.invites.length?`<div class="stack mt">${inv.invites.map(i=>`<div class="invitation"><div><p class="eyebrow">INCOMING LIVE SESSION</p><b>${esc(i.room_name)}</b><div class="tiny">${esc(i.inviter_name)} is calling you into a collaboration room.</div></div><div class="transport"><button class="btn success invite-answer" data-id="${i.id}" data-status="accepted">Answer</button><button class="btn danger invite-answer" data-id="${i.id}" data-status="declined">Decline</button></div></div>`).join('')}</div>`:''}
  <div class="grid four mt"><div class="panel metric"><span>Studio Projects</span><b>${c.projects||0}</b><small>private sessions</small></div><div class="panel metric"><span>Your Beats</span><b>${c.beats||0}</b><small>producer catalog</small></div><div class="panel metric"><span>Releases</span><b>${c.releases||0}</b><small>rights-aware vault</small></div><div class="panel metric"><span>Live Rooms</span><b>${c.rooms||0}</b><small>collaboration access</small></div></div>
  <div class="grid two mt"><div class="panel"><p class="eyebrow">CREATOR PIPELINE</p><h3>From idea to release.</h3><div class="lane-list"><span>1. Record takes</span><span>2. Build / license beat</span><span>3. Live collaboration</span><span>4. Set splits</span><span>5. Save proof</span><span>6. Publish + share</span></div></div><div class="panel"><p class="eyebrow">YOUR ACCESS</p><h3>${esc(roleLabel(state.user.role))}</h3><p class="muted">${state.user.verified?'Verified access is active.':'Your account is active but not yet verified for release publishing.'}</p>${c.users!==undefined?`<div class="status-line"><span class="dot live"></span>${c.users} platform accounts under administration</div>`:''}</div></div>`;
  $$('.invite-answer').forEach(b=>b.onclick=async()=>{await api(`/api/room-invites/${b.dataset.id}/respond`,{method:'POST',body:{status:b.dataset.status}});toast(b.dataset.status==='accepted'?'Session accepted. Open Live Sessions.':'Session declined.','good');renderDashboard()});
