  $('#saveProject').onclick=async()=>{const name=$('#projectName').value.trim()||'Untitled IHD Session';await api('/api/projects',{method:'POST',body:{name,metadata:{savedFrom:'browser-studio',takeCount:state.recordedAssets.length},asset_ids:state.recordedAssets}});toast('Project progress saved to the private server.','good');renderStudio()}
