async function enableStudioMic(){
  try{
    state.micStream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:false,noiseSuppression:false,autoGainControl:false}});state.audioCtx=state.audioCtx||new (window.AudioContext||window.webkitAudioContext)();await state.audioCtx.resume();
    const ctx=state.audioCtx,src=ctx.createMediaStreamSource(state.micStream),gain=ctx.createGain(),hp=ctx.createBiquadFilter(),presence=ctx.createBiquadFilter(),dry=ctx.createGain(),delay=ctx.createDelay(.7),send=ctx.createGain(),feedback=ctx.createGain(),analyser=ctx.createAnalyser(),dest=ctx.createMediaStreamDestination();
    hp.type='highpass';hp.frequency.value=80;presence.type='peaking';presence.frequency.value=3500;presence.Q.value=.9;presence.gain.value=2;delay.delayTime.value=.19;send.gain.value=0;feedback.gain.value=.17;
    src.connect(gain).connect(hp).connect(presence);presence.connect(dry).connect(analyser).connect(dest);presence.connect(send).connect(delay).connect(analyser);delay.connect(feedback).connect(delay);
    $('#gain').oninput=e=>gain.gain.value=+e.target.value;$('#cut').oninput=e=>hp.frequency.value=+e.target.value;$('#presence').oninput=e=>presence.gain.value=+e.target.value;$('#delaySend').oninput=e=>send.gain.value=+e.target.value;
    state.mediaRecorder=new MediaRecorder(dest.stream);state.mediaRecorder.ondataavailable=e=>{if(e.data.size)state.chunks.push(e.data)};state.mediaRecorder.onstop=renderTake;$('#micBtn').disabled=true;$('#recBtn').disabled=false;$('#recState').textContent='MIC READY';$('#recState').className='pill green';drawMeter(analyser);toast('Microphone ready.','good')
  }catch(e){toast('Microphone permission was not granted.','bad')}
}
function startTake(){state.chunks=[];state.mediaRecorder.start(250);$('#recBtn').disabled=true;$('#stopRecBtn').disabled=false;$('#recState').textContent='RECORDING';$('#recState').className='pill red'}
function stopTake(){if(state.mediaRecorder?.state==='recording')state.mediaRecorder.stop();$('#recBtn').disabled=false;$('#stopRecBtn').disabled=true;$('#recState').textContent='TAKE READY';$('#recState').className='pill gold'}
function drawMeter(analyser){const c=$('#meter');if(!c)return;const g=c.getContext('2d'),data=new Uint8Array(analyser.fftSize);function frame(){if(!$('#meter'))return;analyser.getByteTimeDomainData(data);g.clearRect(0,0,c.width,c.height);g.strokeStyle='#d4b06a';g.lineWidth=2;g.beginPath();data.forEach((v,i)=>{const x=i/(data.length-1)*c.width,y=(v/255)*c.height;i?g.lineTo(x,y):g.moveTo(x,y)});g.stroke();state.meterRAF=requestAnimationFrame(frame)}frame()}
function renderTake(){const blob=new Blob(state.chunks,{type:state.mediaRecorder.mimeType||'audio/webm'}),file=new File([blob],`ihd-take-${Date.now()}.webm`,{type:blob.type}),url=URL.createObjectURL(blob),wrap=$('#takes');if(wrap?.querySelector('.empty'))wrap.innerHTML='';const id=`take-${Date.now()}`;const row=document.createElement('div');row.className='take';row.innerHTML=`<div class="wave-chip"></div><audio controls src="${url}"></audio><button class="btn small" id="${id}">Save Private</button>`;wrap?.prepend(row);$(`#${id}`).onclick=async()=>{const btn=$(`#${id}`);btn.disabled=true;btn.textContent='Uploading…';try{const u=await upload('take',file);state.recordedAssets.push(u.asset.id);btn.textContent='Saved ✓';toast('Take saved in private storage.','good')}catch(e){btn.disabled=false;btn.textContent='Retry';toast(e.message,'bad')}}}

async function renderBeats(){
  const d=await api('/api/beats'),p=await api('/api/plugins');const producer=['super_admin','admin','verified_producer'].includes(state.user.role);
  $('#content').innerHTML=`
  <div class="grid two"><div class="panel"><div class="panel-head"><div><p class="eyebrow">16-STEP COOKUP</p><h3>Beat Builder</h3></div><button id="playSeq" class="btn primary">▶ Play Loop</button></div><div class="seq-toolbar"><label>BPM<input id="bpm" type="number" min="60" max="220" value="142"></label><button id="clearSeq" class="btn">Clear</button><button id="randomSeq" class="btn">Spark Idea</button></div><div id="sequencer" class="sequencer mt"></div><p class="tiny">This browser drum machine is an idea tool. Full MIDI, sample slicing, automation and stem bounce are the next DAW layer.</p></div>
  <div class="panel"><p class="eyebrow">PLUGIN RACK</p><h3>Approved Browser Processors</h3><div class="plugin-rack">${p.builtins.map(x=>`<div class="plugin"><b>${esc(x.name)}</b><small>${esc(x.category)}</small><p>WebAudio processor available for safe in-browser chains.</p></div>`).join('')}</div><div class="mt"><p class="kicker">COMMUNITY PRESETS</p><div class="library-list">${p.presets.slice(0,6).map(x=>`<div class="library-item"><div><h5>${esc(x.name)}</h5><p>${esc(x.producer)} • ${x.chain.length} processors</p></div><span class="pill">${esc(x.category)}</span></div>`).join('')||'<div class="empty">No producer chains published yet.</div>'}</div></div></div></div>
  <div class="grid two mt"><div class="panel"><p class="eyebrow">BEAT LIBRARY</p><h3>Available to verified creators</h3><div class="library-list">${d.beats.map(b=>`<div class="library-item"><div><h5>${esc(b.title)}</h5><p>${esc(b.producer)} • ${b.bpm||'—'} BPM • ${esc(b.musical_key||'key not listed')}</p><p>${esc(b.license_text)}</p></div><div class="library-actions">${b.audio_url?`<audio controls preload="none" src="${b.audio_url}" style="max-width:210px"></audio>`:''}</div></div>`).join('')||'<div class="empty">No beats published yet.</div>'}</div></div>
  <div class="panel"><p class="eyebrow">${producer?'PRODUCER ACCESS':'PRODUCER VERIFICATION REQUIRED'}</p><h3>${producer?'Publish new beats + plugin chains':'Get verified to publish'}</h3>${producer?producerPanel():`<p class="muted">Artists can browse the beat library. Master administration controls which accounts receive VERIFIED PRODUCER access.</p>`}</div></div>`;
  initSequencer(); if(producer)initProducerTools();
}
function producerPanel(){return `<label>Beat title<input id="beatTitle" placeholder="Beat title"></label><div class="grid two"><label>BPM<input id="beatBpm" type="number" value="142"></label><label>Key<input id="beatKey" placeholder="F# minor"></label></div><label>Licensing terms<textarea id="beatLicense" rows="3" placeholder="Example: Free for non-profit demo use; commercial use requires written license."></textarea></label><label>Beat audio<input id="beatUpload" type="file" accept="audio/*"></label><div class="progress"><i id="beatProgress"></i></div><button id="publishBeat" class="btn primary wide mt">Upload + Publish Beat</button><hr style="border:0;border-top:1px solid #262a2e;margin:24px 0"><p class="kicker">PUBLISH A SAFE PLUGIN CHAIN</p><label>Preset name<input id="presetName" placeholder="Coach Vocal Heat"></label><label>Processors<select id="presetTypes" multiple size="5"><option value="eq">EQ</option><option value="compressor">Compressor</option><option value="delay">Delay</option><option value="saturator">Saturator</option><option value="reverb">Reverb</option><option value="highpass">High-pass</option><option value="lowpass">Low-pass</option></select></label><button id="publishPreset" class="btn wide">Publish Plugin Preset</button>`}
function initProducerTools(){
  $('#publishBeat').onclick=async()=>{const f=$('#beatUpload').files[0],btn=$('#publishBeat');btn.disabled=true;try{const u=await upload('beat',f,p=>$('#beatProgress').style.width=`${Math.round(p*100)}%`);await api('/api/beats',{method:'POST',body:{title:$('#beatTitle').value,bpm:+$('#beatBpm').value,musical_key:$('#beatKey').value,license_text:$('#beatLicense').value,asset_id:u.asset.id,public:true}});toast('Beat published to the creator library.','good');renderBeats()}catch(e){toast(e.message,'bad')}finally{btn.disabled=false}};
  $('#publishPreset').onclick=async()=>{const types=[...$('#presetTypes').selectedOptions].map(o=>o.value);try{await api('/api/plugins',{method:'POST',body:{name:$('#presetName').value,category:'Producer Chain',chain:types.map(type=>({type}))}});toast('Plugin chain published.','good');renderBeats()}catch(e){toast(e.message,'bad')}}
}
function initSequencer(){
  const tracks=['Kick','Snare','Hat','Perc'],seq=tracks.map(()=>Array(16).fill(false)),wrap=$('#sequencer');tracks.forEach((name,r)=>{const row=document.createElement('div');row.className='seq-row';row.innerHTML=`<span class="seq-name">${name}</span>`;for(let s=0;s<16;s++){const b=document.createElement('button');b.className='step';b.dataset.step=s;b.onclick=()=>{seq[r][s]=!seq[r][s];b.classList.toggle('on')};row.appendChild(b)}wrap.appendChild(row)});
  let playing=false;$('#playSeq').onclick=()=>{playing=!playing;$('#playSeq').textContent=playing?'■ Stop':'▶ Play Loop';if(playing)tick();else{clearTimeout(state.beatTimer);$$('.step').forEach(x=>x.classList.remove('playing'))}};$('#clearSeq').onclick=()=>{seq.forEach(r=>r.fill(false));$$('.step').forEach(x=>x.classList.remove('on'))};$('#randomSeq').onclick=()=>{seq.forEach((r,ri)=>r.forEach((_,i)=>r[i]=Math.random()<(ri===2?.45:.18)));$$('.seq-row').forEach((row,ri)=>$$('.step',row).forEach((b,i)=>b.classList.toggle('on',seq[ri][i])))};
  function tick(){if(!playing)return;state.audioCtx=state.audioCtx||new AudioContext();state.audioCtx.resume();const s=state.beatStep%16;$$('.step').forEach(b=>b.classList.toggle('playing',+b.dataset.step===s));seq.forEach((r,i)=>{if(r[s])drum(i)});state.beatStep++;state.beatTimer=setTimeout(tick,(60000/(+$('#bpm').value||142))/4)}
}
function drum(i){const c=state.audioCtx,t=c.currentTime;if(i===0){const o=c.createOscillator(),g=c.createGain();o.frequency.setValueAtTime(155,t);o.frequency.exponentialRampToValueAtTime(44,t+.14);g.gain.setValueAtTime(.9,t);g.gain.exponentialRampToValueAtTime(.001,t+.2);o.connect(g).connect(c.destination);o.start(t);o.stop(t+.21)}else{const len=i===2?.04:.1,n=Math.floor(c.sampleRate*len),buf=c.createBuffer(1,n,c.sampleRate),a=buf.getChannelData(0);for(let j=0;j<n;j++)a[j]=Math.random()*2-1;const s=c.createBufferSource(),f=c.createBiquadFilter(),g=c.createGain();s.buffer=buf;f.type=i===2?'highpass':'bandpass';f.frequency.value=i===2?7000:1700;g.gain.setValueAtTime(i===2?.22:.5,t);g.gain.exponentialRampToValueAtTime(.001,t+len);s.connect(f).connect(g).connect(c.destination);s.start(t)}}

