  $('#createRoom').onclick=async()=>{try{const d=await api('/api/rooms',{method:'POST',body:{name:$('#newRoomName').value}});toast(`Room ${d.room.code} created.`,'good');openModal(`<p class="eyebrow">ROOM CREATED</p><h3>Share this invite</h3><p>Send this code or link to collaborators:</p><div class="panel"><p class="room-code">${esc(d.room.code)}</p><p class="tiny">${esc(new URL(d.room.share_url, location.origin).href)}</p></div><button class="btn primary wide" id="copyShareLink">Copy link</button></div>`);$('#copyShareLink').onclick=async()=>{await navigator.clipboard.writeText(new URL(d.room.share_url, location.origin).href);toast('Invite link copied.','good')};renderLive()}catch(e){toast(e.message,'bad')}};$('#joinRoom').onclick=async()=>{try{await api('/api/rooms/join',{method:'POST',body:{code:$('#joinCode').value}});toast('Room joined.','good');renderLive()}catch(e){toast(e.message,'bad')}};
  $$('.live-invite').forEach(b=>b.onclick=async()=>{await api(`/api/room-invites/${b.dataset.id}/respond`,{method:'POST',body:{status:b.dataset.status}});renderLive()});
