async function openRoom(room,directory){
  state.room=room;state.signalAfter=0;state.messageAfter=0;state.mediaStarted=false;
  $('#content').innerHTML=`<div class="panel"><div class="panel-head"><div><p class="eyebrow">LIVE COLLABORATION</p><h3>${esc(room.name)}</h3></div><div><div class="room-code">${esc(room.code)}</div><div class="tiny">PRIVATE ROOM CODE</div></div></div><div class="transport"><button id="startMedia" class="btn primary">Start Mic + Camera</button><button id="shareScreen" class="btn" disabled>Share Screen</button><button id="hangup" class="btn danger" disabled>Hang Up</button><button id="copyCode" class="btn">Copy Code</button></div><div id="videoGrid" class="video-grid"><div class="video-tile" id="localTile"><span class="muted">Your camera is off</span><div class="video-label">You • ${esc(state.user.display_name)}</div></div></div></div>
  <div class="grid two mt"><div class="panel"><div class="panel-head"><div><p class="eyebrow">ROOM MEMBERS</p><h3>Invite collaborators</h3></div><span id="roomStatus" class="pill">OFFLINE</span></div><div id="memberList" class="library-list"></div><label>Invite verified user<select id="inviteUser"><option value="">Choose collaborator…</option>${directory.map(u=>`<option value="${u.id}">${esc(u.display_name)} — ${esc(roleLabel(u.role))}</option>`).join('')}</select></label><button id="sendInvite" class="btn wide">Call / Invite Selected User</button></div><div class="panel"><p class="eyebrow">GROUP CHAT</p><h3>Session Feed</h3><div id="chatFeed" class="chat-feed"></div><div class="chat-input"><input id="chatText" placeholder="Message collaborators…"><button id="sendChat" class="btn">Send</button></div></div></div>
  <div class="warning mt"><b>Live session note:</b> this MVP uses your own server for room membership, chat and WebRTC signaling. Browsers connect media peer-to-peer. For internet-scale reliability behind strict NAT/firewalls, deploy a private TURN server or swap the media layer to your self-hosted LiveKit service.</div>`;
  $('#copyCode').onclick=async()=>{await navigator.clipboard.writeText(room.code);toast('Room code copied.','good')};$('#startMedia').onclick=startRoomMedia;$('#shareScreen').onclick=startScreenShare;$('#hangup').onclick=hangUpMedia;$('#sendInvite').onclick=async()=>{const uid=+$('#inviteUser').value;if(!uid)return toast('Choose a collaborator first.','bad');try{await api(`/api/rooms/${room.id}/invite`,{method:'POST',body:{user_id:uid}});toast('Live session invitation sent.','good')}catch(e){toast(e.message,'bad')}};$('#sendChat').onclick=sendChat;$('#chatText').onkeydown=e=>{if(e.key==='Enter')sendChat()};
  await pollRoom();state.roomPoll=setInterval(pollRoom,2500);
}
async function pollRoom(){if(!state.room)return;try{const [m,c,s]=await Promise.all([api(`/api/rooms/${state.room.id}/members`),api(`/api/rooms/${state.room.id}/chat?after=${state.messageAfter}`),api(`/api/rooms/${state.room.id}/signals?after=${state.signalAfter}`)]);renderMembers(m.members);for(const msg of c.messages){state.messageAfter=Math.max(state.messageAfter,msg.id);appendChat(msg)};for(const sig of s.signals){state.signalAfter=Math.max(state.signalAfter,sig.id);await handleSignal(sig)};if(state.mediaStarted)await connectNewPeers(m.members)}catch(e){console.warn(e)}}
function renderMembers(members){const box=$('#memberList');if(!box)return;box.innerHTML=members.map(m=>`<div class="library-item"><div><h5>${esc(m.display_name)}</h5><p>${esc(roleLabel(m.role))} • ${esc(m.permission)}</p></div><span class="status-line"><span class="dot ${m.online?'live':''}"></span>${m.online?'online':'idle'}</span></div>`).join('');const status=$('#roomStatus');if(status){status.textContent=`${members.filter(x=>x.online).length} ONLINE`;status.className='pill green'}}
async function sendChat(){const i=$('#chatText'),body=i?.value.trim();if(!body||!state.room)return;try{await api(`/api/rooms/${state.room.id}/chat`,{method:'POST',body:{body}});i.value='';await pollRoom()}catch(e){toast(e.message,'bad')}}
function appendChat(m){const box=$('#chatFeed');if(!box)return;const d=document.createElement('div');d.className='chat-bubble';d.innerHTML=`<b>${esc(m.display_name)}</b><span>${esc(m.body)}</span>`;box.appendChild(d);box.scrollTop=box.scrollHeight}

async function startRoomMedia(){
  try{state.localStream=await navigator.mediaDevices.getUserMedia({audio:true,video:true});state.mediaStarted=true;const tile=$('#localTile');tile.innerHTML=`<video id="localVideo" autoplay muted playsinline></video><div class="video-label">You • ${esc(state.user.display_name)}</div>`;$('#localVideo').srcObject=state.localStream;$('#startMedia').disabled=true;$('#shareScreen').disabled=false;$('#hangup').disabled=false;toast('You are live in the room.','good');await pollRoom()}catch(e){toast('Camera/microphone permission is required to go live.','bad')}
}
async function connectNewPeers(members){for(const m of members){if(m.id===state.user.id||!m.online||state.peers.has(m.id))continue;if(state.user.id<m.id){const pc=createPeer(m.id,m.display_name);const offer=await pc.createOffer();await pc.setLocalDescription(offer);await sendSignal(m.id,'offer',offer)}}}
function createPeer(peerId,name='Collaborator'){
  if(state.peers.has(peerId))return state.peers.get(peerId);const pc=new RTCPeerConnection({iceServers:state.iceServers});state.peers.set(peerId,pc);state.localStream?.getTracks().forEach(t=>pc.addTrack(t,state.localStream));state.screenStream?.getTracks().forEach(t=>pc.addTrack(t,state.screenStream));pc.onicecandidate=e=>{if(e.candidate)sendSignal(peerId,'ice',e.candidate)};pc.ontrack=e=>attachRemote(peerId,name,e.streams[0]);pc.onconnectionstatechange=()=>{if(['failed','closed','disconnected'].includes(pc.connectionState)){removePeer(peerId)}};return pc
}
function attachRemote(id,name,stream){const grid=$('#videoGrid');if(!grid)return;let tile=$(`#peer-${id}`);if(!tile){tile=document.createElement('div');tile.id=`peer-${id}`;tile.className='video-tile';tile.innerHTML=`<video autoplay playsinline></video><div class="video-label">${esc(name)}</div>`;grid.appendChild(tile)}$('video',tile).srcObject=stream}
async function sendSignal(to,type,payload){if(!state.room)return;try{await api(`/api/rooms/${state.room.id}/signal`,{method:'POST',body:{to,type,payload}})}catch(e){console.warn('signal',e)}}
async function handleSignal(s){const from=s.from_user_id;if(s.signal_type==='hangup'){removePeer(from);return}let pc=state.peers.get(from);if(s.signal_type==='offer'){pc=pc||createPeer(from,`User ${from}`);await pc.setRemoteDescription(new RTCSessionDescription(s.payload));const ans=await pc.createAnswer();await pc.setLocalDescription(ans);await sendSignal(from,'answer',ans)}else if(s.signal_type==='answer'&&pc){await pc.setRemoteDescription(new RTCSessionDescription(s.payload))}else if(s.signal_type==='ice'){pc=pc||createPeer(from,`User ${from}`);try{await pc.addIceCandidate(new RTCIceCandidate(s.payload))}catch(e){console.warn(e)}}}
async function startScreenShare(){try{state.screenStream=await navigator.mediaDevices.getDisplayMedia({video:true,audio:true});for(const [id,pc] of state.peers){for(const t of state.screenStream.getTracks())pc.addTrack(t,state.screenStream);const offer=await pc.createOffer();await pc.setLocalDescription(offer);await sendSignal(id,'offer',offer)}state.screenStream.getVideoTracks()[0].onended=()=>{state.screenStream=null;toast('Screen sharing stopped.')};toast('Screen share started.','good')}catch(e){toast('Screen sharing was cancelled.','bad')}}
function removePeer(id){const pc=state.peers.get(id);if(pc)pc.close();state.peers.delete(id);$(`#peer-${id}`)?.remove()}
async function hangUpMedia(){for(const id of state.peers.keys())sendSignal(id,'hangup',{});state.localStream?.getTracks().forEach(t=>t.stop());state.screenStream?.getTracks().forEach(t=>t.stop());for(const id of [...state.peers.keys()])removePeer(id);state.localStream=null;state.screenStream=null;state.mediaStarted=false;const tile=$('#localTile');if(tile)tile.innerHTML=`<span class="muted">Your camera is off</span><div class="video-label">You • ${esc(state.user.display_name)}</div>`;if($('#startMedia'))$('#startMedia').disabled=false;if($('#shareScreen'))$('#shareScreen').disabled=true;if($('#hangup'))$('#hangup').disabled=true}
function cleanupRoom(){if(state.roomPoll){clearInterval(state.roomPoll);state.roomPoll=null}hangUpMedia().catch(()=>{});state.room=null}

