async function renderLegal(){
  $('#content').innerHTML=`<div class="hero panel"><div><p class="eyebrow">POLICY CENTER</p><h3>Protect creators without pretending every dispute is simple.</h3><p>These are product-ready policy foundations for IT HIT DIFFERENT LLC. Final public legal copy should be reviewed for the jurisdictions where the company and users operate.</p></div><div class="hero-stamp"><b>§</b>RIGHTS + PRIVACY</div></div>
  <div class="grid two mt"><div class="panel"><p class="eyebrow">PRIVACY POLICY — DRAFT STRUCTURE</p><h3>What the platform should disclose</h3><ul class="clean"><li><b>Account information:</b> name/display name, email, verification status, roles and security records.</li><li><b>Creator content:</b> recordings, stems, beats, artwork, releases, agreements, split data, EPK materials and project metadata.</li><li><b>Collaboration data:</b> room membership, invitations, chat messages and live-session technical metadata. The MVP does not server-record room media.</li><li><b>Security/operations:</b> IP/security logs, audit events, device/session data and abuse-prevention signals.</li><li><b>Purpose:</b> authenticate users, operate studios/rooms, store projects, publish releases, enforce rights rules and protect the service.</li><li><b>Retention:</b> define retention by data category, backups, legal holds and user-request workflows.</li><li><b>Sharing:</b> identify infrastructure/payment/analytics subprocessors and never sell private studio files as advertising data.</li><li><b>User controls:</b> account data access/export, correction, deletion requests and withdrawal of optional consents where applicable.</li><li><b>Minors:</b> define age rules and parental/guardian processes with counsel before accepting minors.</li><li><b>Security:</b> encryption, private storage, access controls, incident response and breach notification practices.</li></ul></div>
  <div class="panel"><p class="eyebrow">COPYRIGHT / INFRINGEMENT</p><h3>Notice + dispute workflow</h3><div class="course"><div class="course-step"><b>1. Rights declaration at upload.</b><p>Uploader confirms ownership/control or permission before publishing.</p></div><div class="course-step"><b>2. Receive a specific complaint.</b><p>Collect claimant identity/contact, work identification, allegedly infringing material, location, good-faith statements and signature/evidence as required by the adopted policy.</p></div><div class="course-step"><b>3. Preserve the record.</b><p>Keep the policy version, upload attestation, asset identifiers, timestamps and submitted evidence.</p></div><div class="course-step"><b>4. Restrict material when required.</b><p>Do not have an automated AI system decide disputed ownership. Follow the published process and counsel-reviewed legal obligations.</p></div><div class="course-step"><b>5. Counter-notice / dispute route.</b><p>Provide the legally appropriate response process, deadlines and restoration rules where applicable.</p></div><div class="course-step"><b>6. Repeat-infringer enforcement.</b><p>Maintain and consistently apply the written policy while protecting evidence and appeal records.</p></div></div></div></div>
  <div class="grid two mt"><div class="panel"><p class="eyebrow">ENTERTAINMENT LAWYER + MANAGEMENT</p><h3>Teach users how to vet representation</h3><ul class="clean"><li>Ask what music/entertainment matters the lawyer regularly handles and where they are licensed.</li><li>Understand engagement letters, scope, hourly/flat/contingent fees and conflicts before representation begins.</li><li>For managers/agents, verify track record, references, commission structure, term, territory, authority and termination rights.</li><li>Do not give a manager the platform master password. Grant scoped team permissions instead.</li><li>Material recording, publishing, management, label, distribution or catalog-sale contracts deserve qualified review before signature.</li></ul></div><div class="panel"><p class="eyebrow">DBA • EIN • TAX • ENTITY</p><h3>Business setup education</h3><ul class="clean"><li>Entity formation and assumed-name/DBA requirements are jurisdiction-specific.</li><li>An EIN is a federal tax identifier; users should be directed to official government channels rather than charged merely for access to the application.</li><li>Separate business and personal banking/accounting where appropriate.</li><li>Track contracts, invoices, royalty statements, expenses and tax records.</li><li>Use a qualified attorney/CPA/tax professional for individualized entity, tax-election, payroll and filing decisions.</li></ul><div class="warning mt">The platform can provide checklists, official links and document organization. It should not tell every user that one entity structure or tax treatment is automatically right for them.</div></div></div>`;
}

async function renderAccount(){
  $('#content').innerHTML=`<div class="grid two"><div class="panel"><p class="eyebrow">ACCOUNT SECURITY</p><h3>Change password</h3><label>Current password<input id="curPass" type="password" autocomplete="current-password"></label><label>New password<input id="newPass" type="password" autocomplete="new-password" placeholder="12+ characters"></label><label>Confirm new password<input id="confirmPass" type="password" autocomplete="new-password"></label><button id="savePass" class="btn primary wide">Update Password</button></div><div class="panel"><p class="eyebrow">CURRENT AUTHORITY</p><h3>${esc(roleLabel(state.user.role))}</h3><p class="muted">${esc(state.user.email)}</p><div class="lane-list"><span>${state.user.verified?'Verified':'Unverified'}</span><span>${state.user.suspended?'Suspended':'Active'}</span><span>Server session</span><span>CSRF protected</span></div><div class="warning mt">The master owner is intentionally protected from being demoted or suspended through delegated admin controls. Production should add passkeys/MFA, recovery codes and session/device revocation.</div></div></div>`;$('#savePass').onclick=async()=>{const n=$('#newPass').value;if(n!==$('#confirmPass').value)return toast('New passwords do not match.','bad');try{await api('/api/account/password',{method:'POST',body:{current_password:$('#curPass').value,new_password:n}});state.user.must_change_password=false;toast('Password updated.','good');$('#curPass').value=$('#newPass').value=$('#confirmPass').value=''}catch(e){toast(e.message,'bad')}}
}

async function renderAdmin(){
  if(!['super_admin','admin'].includes(state.user.role))return go('dashboard');const [u,a]=await Promise.all([api('/api/admin/users'),api('/api/admin/audit')]);
  $('#content').innerHTML=`<div class="hero panel"><div><p class="eyebrow">MASTER CONTROL</p><h3>IT HIT DIFFERENT LLC owner authority.</h3><p>Create accounts, assign creator/artist/producer roles, verify access, suspend bad actors and review security events. The SUPER_ADMIN identity itself is protected from delegated changes.</p></div><div class="hero-stamp"><b>${u.users.length}</b>ACCOUNTS</div></div>
  <div class="grid two mt"><div class="panel"><p class="eyebrow">CREATE / INVITE USER</p><h3>Grant network access</h3><label>Display name<input id="newUserName" placeholder="Artist / producer name"></label><label>Email<input id="newUserEmail" type="email" placeholder="user@example.com"></label><label>Role<select id="newUserRole"><option value="creator">Creator</option><option value="verified_artist">Verified Artist</option><option value="verified_producer">Verified Producer</option>${state.user.role==='super_admin'?'<option value="admin">Admin</option>':''}</select></label><button id="createUser" class="btn primary wide">Create Account + Temporary Password</button></div><div class="panel"><p class="eyebrow">OWNER RULES</p><h3>Control without a backdoor.</h3><ul class="clean"><li>Only one bootstrap SUPER_ADMIN.</li><li>Delegated admins cannot modify the master owner.</li><li>Only the master can grant administrator status.</li><li>Suspension revokes active sessions.</li><li>Every sensitive action produces an audit event.</li></ul></div></div>
  <div class="panel table-wrap mt"><div class="panel-head"><div><p class="eyebrow">USER DIRECTORY</p><h3>Verification + access</h3></div></div><table class="admin-table"><thead><tr><th>USER</th><th>ROLE</th><th>VERIFIED</th><th>STATUS</th><th>ACTIONS</th></tr></thead><tbody>${u.users.map(x=>`<tr><td><b>${esc(x.display_name)}</b><div class="tiny">${esc(x.email)}</div></td><td><span class="role-badge">${esc(roleLabel(x.role))}</span></td><td>${x.verified?'YES':'NO'}</td><td>${x.suspended?'SUSPENDED':'ACTIVE'}</td><td>${x.role==='super_admin'?'<span class="pill gold">MASTER PROTECTED</span>':`<button class="btn small admin-toggle" data-id="${x.id}" data-field="verified" data-value="${!x.verified}">${x.verified?'Unverify':'Verify'}</button> <button class="btn small ${x.suspended?'success':'danger'} admin-toggle" data-id="${x.id}" data-field="suspended" data-value="${!x.suspended}">${x.suspended?'Restore':'Suspend'}</button>`}</td></tr>`).join('')}</tbody></table></div>
  <div class="panel mt"><p class="eyebrow">AUDIT LOG</p><h3>Recent platform activity</h3><div class="audit">${a.events.map(e=>`<div class="audit-row"><span>${esc(fmtDate(e.created_at))}</span><b>${esc(e.actor||'System')}</b><div><span class="tag">${esc(e.action)}</span> <span>${esc(e.target||'')}</span></div></div>`).join('')||'<div class="empty">No audit events yet.</div>'}</div></div>`;
  $('#createUser').onclick=async()=>{try{const d=await api('/api/admin/users',{method:'POST',body:{display_name:$('#newUserName').value,email:$('#newUserEmail').value,role:$('#newUserRole').value}});openModal(`<p class="eyebrow">ACCOUNT CREATED</p><h2>Temporary credentials</h2><p class="muted">Send this password to the user through a secure channel. It is returned only in this response.</p><div class="panel"><b>${esc($('#newUserEmail').value)}</b><div class="room-code" style="font-size:20px;margin-top:10px;word-break:break-all">${esc(d.temporary_password)}</div></div><p class="tiny">The user will be prompted to change the temporary password after signing in.</p>`);renderNav()}catch(e){toast(e.message,'bad')}};
  $$('.admin-toggle').forEach(b=>b.onclick=async()=>{const body={[b.dataset.field]:b.dataset.value==='true'};try{await api(`/api/admin/users/${b.dataset.id}/status`,{method:'POST',body});toast('User access updated.','good');renderAdmin()}catch(e){toast(e.message,'bad')}})
}

boot();
